<?php
use EIPSI\ExternalApi as A;
use EIPSI\StudyEngine\Persistence as P;
d2_case('Two historical StudyVersions retain rows and versioned dictionaries after renaming',function(){ $p=d2_publish();d2_finish($p,'V1_HISTORY');$d=pe_definition('simple',$p['definition']['study']['logical_id'],$p['public'],2);foreach($d['nodes']as&$n)if($n['kind']==='QUESTION'){$c=json_decode($n['content']['snapshot'],true);$c['label']='Renamed historical variable';$n['content']['snapshot']=EIPSI\StudyEngine\Contracts\Canonical::json($c);$n['content']['sha256']=hash('sha256',$n['content']['snapshot']);}unset($n);$v2=d2_publish(false,$d);d2_finish($v2,'V2_HISTORY');$k=d2_key(array($p['definition']['study']['logical_id']));$rows=d2_read($k,array(),$p)['items'];d2_assert(count($rows)===2&&count(array_unique(array_column($rows,'study_version_id')))===2);$dict=d2_read($k,array(),$p,true)['items'];d2_assert(count($dict)===2&&count(array_unique(array_column($dict,'label')))===2);d2_parity($rows,d2_management($p));});
d2_case('Longitudinal reopening preserves historical cycles and finalized data',function()use($builder){$p=d2_publish(true);d2_finish($p,'CYCLE_ONE');$k=d2_key(array($p['definition']['study']['logical_id']));$s=$builder->load($p['version']);$builder->changeStudyState($s['id'],$s['lifecycle']['revision'],'FINALIZED',true,'API2_FINALIZE');d2_assert(count(d2_read($k,array(),$p)['items'])===1);$s=$builder->load($p['version']);$builder->changeStudyState($s['id'],$s['lifecycle']['revision'],'REOPEN',true,'API2_REOPEN');d2_finish($p,'CYCLE_TWO');$rows=d2_read($k,array(),$p)['items'];$cycles=array_unique(array_column($rows,'cycle'));sort($cycles);d2_assert($cycles===array(1,2));d2_parity($rows,d2_management($p));});
d2_case('Paused and archived Studies remain scientifically readable',function()use($builder){$p=d2_publish();d2_finish($p);$k=d2_key(array($p['definition']['study']['logical_id']));$s=$builder->load($p['version']);$builder->changeStudyState($s['id'],$s['lifecycle']['revision'],'PAUSED',false,'API2_PAUSE');d2_assert(count(d2_read($k,array(),$p)['items'])===1);$s=$builder->load($p['version']);$builder->archiveStudy($s['id'],$s['revision']);d2_assert(count(d2_read($k,array(),$p)['items'])===1);});
d2_case('Real B1 retained data remains usable and B2 is excluded before and after cleanup',function(){ $p=d2_publish(true);$a=d2_finish($p,'USE_ALLOWED_VALUE');$b=d2_finish($p,'DO_NOT_USE_SECRET');$c=d2_finish($p,'RETAINED_VALUE');d2_withdraw($b['frame'],'DO_NOT_USE');d2_withdraw($c['frame'],'RETAIN_FOR_ANALYSIS');$k=d2_key(array($p['definition']['study']['logical_id']));$rows=d2_read($k,array(),$p)['items'];d2_assert(count($rows)===2&&in_array('RETAIN_FOR_ANALYSIS',array_column($rows,'data_policy'),true));d2_assert(strpos(json_encode($rows),'DO_NOT_USE_SECRET')===false);d2_parity($rows,d2_management($p));EIPSI_Privacy_Data_Cleanup_Service::run_study_engine(pf_db(),$b['frame']['access']['execution_id']);d2_assert(count(d2_read($k,array(),$p)['items'])===2);});
d2_case('Persisted domain partial is explicit and never presented as completed',function(){ $p=d2_publish(true);$f=pf_enroll($p);$block=$f['view']['next_action']['payload']['assessment_execution_id'];$graph=(new P\StudyVersionRepository(pf_db()))->compiled((new P\StudyVersionRepository(pf_db()))->find($p['version']));$answers=(new EIPSI\StudyEngine\Content\ResponseAdapter())->decode($p['definition'],array('R_q1'=>'DOMAIN_PARTIAL'),$graph->descendants($f['view']['snapshot']['instances'][$block]['definition_id']));pf_dispatch($f,'SAVE_PAGE',array('block_execution_id'=>$block,'responses'=>$answers));$k=d2_key(array($p['definition']['study']['logical_id']));d2_assert(d2_read($k,array(),$p)['items']===array());$rows=d2_read($k,array('include_partials'=>'true'),$p)['items'];d2_assert(count($rows)===1&&$rows[0]['attempt_state']!=='COMPLETED');d2_parity($rows,d2_management($p,true));});
d2_case('Native Likert VAS Matrix multiple text date and numbers preserve scientific types',function(){ $n=d2_native();$p=$n['p'];$k=d2_key(array($p['definition']['study']['logical_id']));$rows=d2_read($k,array(),$p)['items'];$by=array_column($rows,null,'type');d2_assert(is_numeric($by['likert']['value'])&&is_numeric($by['vas']['value'])&&is_array($by['multiple_choice']['value'])&&is_int($by['number']['value']));d2_assert($by['likert']['selected_option_id']!==null&&$by['date']['value']==='2026-10-18');$matrix=array_values(array_filter($rows,static function($r){return$r['type']==='matrix';}));d2_assert(count($matrix)>=2&&$matrix[0]['variable_name']!==$matrix[1]['variable_name']);d2_parity($rows,d2_management($p));$dict=d2_read($k,array(),$p,true)['items'];foreach($rows as$r){$matches=array_values(array_filter($dict,static function($d)use($r){return$d['response_key']===$r['response_key']&&$d['variable_name']===$r['variable_name']&&$d['definition_hash']===$r['definition_hash'];}));d2_assert(count($matches)===1,'Dictionary row not interpretable');} $GLOBALS['nativeComplete']=$n;});
d2_case('Native expired saved partials are off by default and retain PARTIAL_SAVED state',function(){ $n=d2_native(false);$p=$n['p'];$n['clock']->now+=86400*31;$n['owner']->view($n['id']);$k=d2_key(array($p['definition']['study']['logical_id']));d2_assert(d2_read($k,array(),$p)['items']===array());$rows=d2_read($k,array('include_partials'=>'true'),$p)['items'];d2_assert(count($rows)>=7&&array_unique(array_column($rows,'attempt_state'))===array('PARTIAL_SAVED'));d2_parity($rows,d2_management($p,true));});
d2_case('Scientific consultation leaves checkpoints opportunities decisions queues and mail unchanged',function(){global$p;$k=d2_key();$tables=array('study_executions','block_executions','random_decisions','notification_intents');$before=array();foreach($tables as$t)$before[$t]=hash('sha256',json_encode(pf_db()->rows('SELECT * FROM '.pf_db()->table($t).' ORDER BY id')));$mail=count($GLOBALS['m0_mail']??array());d2_read($k);d2_read($k,array('format'=>'csv'));d2_read($k,array(),null,true);foreach($tables as$t)d2_assert($before[$t]===hash('sha256',json_encode(pf_db()->rows('SELECT * FROM '.pf_db()->table($t).' ORDER BY id'))));d2_assert($mail===count($GLOBALS['m0_mail']??array()));});

d2_case('Optional unanswered Native values remain null with an explicit response status',function(){$n=d2_native(true,false,true);$p=$n['p'];$rows=d2_read(d2_key(array($p['definition']['study']['logical_id'])),array(),$p)['items'];$date=array_values(array_filter($rows,static function($r){return$r['type']==='date';}))[0];d2_assert($date['value']===null&&$date['response_status']==='NO_VALUE_RECORDED');});
d2_case('Randomized candidates have one real value and explicit nonselected status without invented answers',function(){$n=d2_native(true,true);$p=$n['p'];$rows=d2_read(d2_key(array($p['definition']['study']['logical_id'])),array(),$p)['items'];d2_assert(count($rows)===2);$values=array_values(array_filter($rows,static function($r){return$r['value']!==null;}));$not=array_values(array_filter($rows,static function($r){return$r['response_status']==='NOT_SELECTED_BY_RANDOMIZATION';}));d2_assert(count($values)===1&&count($not)===1&&$not[0]['value']===null);d2_parity($rows,d2_management($p));});
d2_case('Dictionary stays pinned after the current Assessment renames a variable and deletes a question',function(){$n=d2_native();$p=$n['p'];$d=$n['definition'];$old=$d['elements'][0]['properties']['variable_name'];$d['elements'][0]['properties']['variable_name']='new_name_not_collected';$d['elements']=array_values(array_filter($d['elements'],static function($e){return$e['type']!=='date';}));$d['flow']['pages']=array();$d=EIPSI\AssessmentEditor\Definition::validate($d);EIPSI\AssessmentEditor\Repository::save($d,1);$v=$n['owner']->publish($d['id'],2);$GLOBALS['nativeFixtures'][]=array('assessment'=>$d['id'],'version'=>$v['version_id']);$k=d2_key(array($p['definition']['study']['logical_id']));$dict=d2_read($k,array(),$p,true)['items'];d2_assert(in_array($old,array_column($dict,'variable_name'),true)&&!in_array('new_name_not_collected',array_column($dict,'variable_name'),true));d2_assert(in_array('date',array_column($dict,'type'),true));});
d2_case('as_of is the dataset reading clock and never participant saved_at',function(){ $k=d2_key();$fixed=strtotime('2031-02-03T04:05:06Z');$r=(new A\StudyDataExport(static function()use($fixed){return$fixed;}))->read($k['principal'],$GLOBALS['p']['public']);d2_assert($r['as_of']==='2031-02-03T04:05:06Z'&&$r['items'][0]['saved_at']!==$r['as_of']);});
d2_case('Boolean scientific values stay boolean in JSON and textual in safe CSV',function(){ $p=d2_publish(false,pe_definition('consent'));$f=pe_runtime()->handle($p['public']);$done=pe_runtime()->handle($p['public'],$f['token'],pe_request($f,'submit',array('R_consent'=>'true','R_follow'=>'FOLLOW')));d2_assert($done['view']['next_action']['kind']==='FINISHED');$k=d2_key(array($p['definition']['study']['logical_id']));$rows=d2_read($k,array(),$p)['items'];$boolean=array_values(array_filter($rows,static function($r){return$r['type']==='BOOLEAN';}));d2_assert(count($boolean)===1&&$boolean[0]['value']===true);d2_assert(strpos(d2_read($k,array('format'=>'csv'),$p)['csv'],'true')!==false);});
